var 分类列表 = [];

function start() {
    for (var 分类 in 起源奖池) {
        分类列表.push(分类);
    }
    if (分类列表.length === 0) {
        cm.sendOk("奖池数据为空，请联系管理员。");
        cm.dispose();
        return;
    }
    页面 = "分类";
    显示分类菜单();
}

var 页面 = "分类";
var 当前分类 = "";
var 当前页 = 0;

function action(mode, type, selection) {
    if (mode === -1 || mode === 0) {
        cm.dispose();
        return;
    }
    if (页面 === "分类") {
        进入分类(selection);
    } else if (页面 === "列表") {
        处理列表选择(selection);
    } else if (页面 === "详情") {
        显示列表();
    } else {
        cm.dispose();
    }
}

// ============================================================
// 分类菜单
// ============================================================
function 显示分类菜单() {
    var 文本 = "#e#d【起源之塔 · 奖池预览】#k#n\r\n";
    var 总数 = 0;
    for (var i = 0; i < 分类列表.length; i++) {
        总数 += 起源奖池[分类列表[i]].length;
    }
    文本 += "奖池共 #r" + 总数 + "#k 件装备，全部等概率抽取。\r\n";
    文本 += "#d----------------------------------------#k\r\n";
    文本 += "#e#b请选择要查看的分类：#k#n\r\n";
    for (var n = 0; n < 分类列表.length; n++) {
        var 名单 = 起源奖池[分类列表[n]];
        var 样例 = 名单[0];
        文本 += "#v" + 样例 + "# #L" + n + "##b" + 分类列表[n] + "#k       #d共 " + 名单.length + " 件#k#l\r\n";
    }
    页面 = "分类";
    cm.sendSimple(文本);
}

function 进入分类(selection) {
    if (selection < 0 || selection >= 分类列表.length) {
        cm.dispose();
        return;
    }
    当前分类 = 分类列表[selection];
    当前页 = 0;
    显示列表();
}

// ============================================================
// 装备清单
// ============================================================
function 显示列表() {
    var 名单 = 起源奖池[当前分类];
    var 总页数 = Math.max(1, Math.ceil(名单.length / 每页件数));
    if (当前页 < 0) {
        当前页 = 0;
    }
    if (当前页 > 总页数 - 1) {
        当前页 = 总页数 - 1;
    }
    var 起点 = 当前页 * 每页件数;
    var 终点 = Math.min(名单.length, 起点 + 每页件数);

    var 文本 = "#e#d【" + 当前分类 + " · 第 " + (当前页 + 1) + "/" + 总页数 + " 页】#k#n";
    文本 += "  #d共 " + 名单.length + " 件#k\r\n";
    文本 += "#d----------------------------------------#k\r\n";

    for (var i = 起点; i < 终点; i++) {
        var 序 = i - 起点 + 1;
        // 图标放在链接外（悬停才收得到事件），名称放在链接内（点击进详情）——
        // 拆成两段的原因见文件头。序号也用本页内偏移，避免超过对话框的选择值上限。
        文本 += "#v" + 名单[i] + "# #L" + (i - 起点) + "#"
            + (序 < 10 ? " " : "") + 序 + "  #t" + 名单[i] + "##l\r\n";
    }

    文本 += "#d----------------------------------------#k\r\n";
    文本 += "#d点击名称看完整属性；鼠标移到图标上可看装备说明。#k\r\n";
    if (总页数 > 1) {
        if (当前页 > 0) {
            文本 += "#L900001##b【上一页】#k#l   ";
        }
        文本 += "第 #r" + (当前页 + 1) + "#k / " + 总页数 + " 页   ";
        if (当前页 < 总页数 - 1) {
            文本 += "#L900002##b【下一页】#k#l   ";
        }
        文本 += "\r\n";
    }
    文本 += "#L900003##b【返回分类】#k#l";
    页面 = "列表";
    cm.sendSimple(文本);
}

function 处理列表选择(selection) {
    if (selection === 900001) {
        当前页--;
        显示列表();
        return;
    }
    if (selection === 900002) {
        当前页++;
        显示列表();
        return;
    }
    if (selection === 900003) {
        显示分类菜单();
        return;
    }
    var 名单 = 起源奖池[当前分类];
    var 序号 = 当前页 * 每页件数 + selection;
    if (序号 < 0 || 序号 >= 名单.length) {
        cm.dispose();
        return;
    }
    显示详情(名单[序号]);
}

// ============================================================
// 装备详情
// ============================================================
// BEGIN 装备属性
// 装备属性的读取与排版。奖池预览与积分商店共用同一份实现
// （由 tool/scripts/migration/seed_tower_rewards.py 注入，契约测试核对两份逐字节相同）。
//
// ★ 键名注意：服务端 ItemInformationProvider.getEquipStats() 会把 info 里以 "inc"
// 开头的字段**去掉前缀**再放进 Map（见 ItemInformationProvider.java:575-577）：
//   incPAD -> PAD, incSTR -> STR, incPDD -> PDD, incSpeed -> Speed, incJump -> Jump ...
// 所以下面必须写去掉前缀后的名字；写 incPAD 会永远查不到值、属性整段空白且不报错。
// reqLevel/reqJob/reqSTR/reqDEX/reqINT/reqLUK/reqPOP/cash/tuc/only 是原样入表的。
var 装备_需求项 = [
    ["reqLevel", "等级要求"],
    ["reqSTR", "力量要求"],
    ["reqDEX", "敏捷要求"],
    ["reqINT", "智力要求"],
    ["reqLUK", "运气要求"],
    ["reqPOP", "人气要求"]
];
// 加成项的名字 = WZ 里的 incXXX 去掉 "inc"。这份清单是按奖池 1153 件
// （脸饰/耳环/项环/腰带）实际出现过的字段统计的，覆盖全部 20 个。
var 装备_加成项 = [
    ["PAD", "物理攻击力"],
    ["MAD", "魔法攻击力"],
    ["STR", "力量"],
    ["DEX", "敏捷"],
    ["INT", "智力"],
    ["LUK", "运气"],
    ["PDD", "物理防御力"],
    ["MDD", "魔法防御力"],
    ["ACC", "命中率"],
    ["EVA", "回避率"],
    ["MHP", "最大HP"],
    ["MMP", "最大MP"],
    ["MHPr", "最大HP%"],
    ["MMPr", "最大MP%"],
    ["Speed", "移动速度"],
    ["MSpeed", "移动速度%"],
    ["Jump", "跳跃力"],
    ["PVPDamage", "PVP伤害"],
    ["Craft", "制作技能"],
    ["CriticalMAXDamage", "暴击最大伤害"]
];

var 装备_部位名 = { "101": "脸饰", "103": "耳环", "112": "项环", "113": "腰带" };

function 装备_部位文本(道具ID) {
    var 段 = String(Math.floor(道具ID / 10000));
    return 装备_部位名[段] || ("道具 " + 段 + " 段");
}

// 读一件装备的全部 info 数值（键名已按上面的规则去过 inc 前缀）。
// 读失败时返回 {读取失败:true}，让调用方显式提示，而不是静默显示成"无附加属性"。
function 装备_取属性(道具ID) {
    var 结果 = {};
    try {
        var II = Java.type("org.gms.server.ItemInformationProvider").getInstance();
        var 映射 = II.getEquipStats(道具ID);
        if (映射 === null || 映射 === undefined) {
            return 结果;
        }
        var 迭代 = 映射.entrySet().iterator();
        while (迭代.hasNext()) {
            var 键值 = 迭代.next();
            var 值 = 键值.getValue();
            结果[String(键值.getKey())] = (值 === null || 值 === undefined) ? 0 : Number(值);
        }
    } catch (e) {
        结果.读取失败 = true;
    }
    return 结果;
}

function 装备_职业文本(掩码) {
    var 表 = [[1, "战士"], [2, "法师"], [4, "弓箭手"], [8, "飞侠"], [16, "海盗"]];
    var 名 = [];
    for (var i = 0; i < 表.length; i++) {
        if ((掩码 & 表[i][0]) !== 0) {
            名.push(表[i][1]);
        }
    }
    return 名.length > 0 ? 名.join("/") : "全职业";
}

// 需求行 [[标签, 值], ...]：职业位掩码排最前，其余按 装备_需求项 的顺序。
function 装备_需求行(属性) {
    var 行 = [];
    if (属性.reqJob && 属性.reqJob > 0) {
        行.push(["职业要求", 装备_职业文本(属性.reqJob)]);
    }
    for (var i = 0; i < 装备_需求项.length; i++) {
        var 值 = 属性[装备_需求项[i][0]];
        if (值 && 值 > 0) {
            行.push([装备_需求项[i][1], String(值)]);
        }
    }
    return 行;
}

// 加成行：已经是带好颜色标记的成品字符串，调用方直接逐行输出即可。
function 装备_加成行(属性) {
    var 行 = [];
    for (var i = 0; i < 装备_加成项.length; i++) {
        var 值 = 属性[装备_加成项[i][0]];
        if (值 && 值 !== 0) {
            行.push(装备_加成项[i][1] + " +#r" + 值 + "#k");
        }
    }
    if (属性.tuc && 属性.tuc > 0) {
        行.push("可升级次数 +#r" + 属性.tuc + "#k");
    }
    return 行;
}

// 半角宽度：中文按 2 格、ASCII 按 1 格。客户端点阵字体里全角正好是半角的两倍宽，
// 用这个单位补空格就能让两段文字左右对齐。对话框没有制表位，别用 	 去对齐。
function 文本_宽度(文本) {
    var 宽 = 0;
    for (var i = 0; i < 文本.length; i++) {
        宽 += (文本.charCodeAt(i) > 0x7F) ? 2 : 1;
    }
    return 宽;
}

function 文本_补右(文本, 目标宽) {
    var 缺 = 目标宽 - 文本_宽度(文本);
    return 缺 > 0 ? 文本 + new Array(缺 + 1).join(" ") : 文本;
}

function 文本_补左(文本, 目标宽) {
    var 缺 = 目标宽 - 文本_宽度(文本);
    return 缺 > 0 ? new Array(缺 + 1).join(" ") + 文本 : 文本;
}
// END 装备属性

function 显示详情(道具ID) {
    var 文本 = "#e#b#t" + 道具ID + "##k#n\r\n";
    文本 += "#v" + 道具ID + "#\r\n";
    文本 += "#d----------------------------------------#k\r\n";
    文本 += "部位：#b" + 装备_部位文本(道具ID) + "#k\r\n";

    var 属性 = 装备_取属性(道具ID);
    var 行 = 装备_需求行(属性);
    var 加成 = 装备_加成行(属性);

    文本 += "#e需求#n\r\n";
    if (行.length > 0) {
        for (var a = 0; a < 行.length; a++) {
            文本 += "  " + 行[a][0] + "：#r" + 行[a][1] + "#k\r\n";
        }
    } else {
        文本 += "  #d无等级/属性要求#k\r\n";
    }

    文本 += "#e基础属性#n\r\n";
    if (加成.length > 0) {
        for (var b = 0; b < 加成.length; b++) {
            文本 += "  " + 加成[b] + "\r\n";
        }
    } else {
        文本 += "  #d无附加属性#k\r\n";
    }

    // 交易/佩戴标记（不是数值加成，单独一行说明）
    var 标记 = [];
    if (属性.cash) {
        标记.push("现金道具");
    }
    if (属性.tradeBlock) {
        标记.push("不可交易");
    }
    if (属性.only) {
        标记.push("唯一装备");
    }
    if (标记.length > 0) {
        文本 += "#d（" + 标记.join("、") + "）#k\r\n";
    }
    if (属性.读取失败) {
        文本 += "#d（属性读取失败，请反馈管理员）#k\r\n";
    }
    文本 += "#d----------------------------------------#k\r\n";
    文本 += "#d点击「确定」返回列表。#k";

    // 点掉这个提示框后回到当前页清单
    页面 = "详情";
    cm.sendOk(文本);
}

